"use client";
import Link from 'next/link';
import { projects, ICONS } from '@/lib/data';
import { useState } from "react";
import BootSequence from "./boot";
import type { NourPath } from "@/lib/nour-path";

export default function HomeClient({
  nourPath,
  nourViewBox,
  nourStrokeWidth,
}: {
  nourPath: NourPath;
  nourViewBox: string;
  nourStrokeWidth: number;
}) {
  const [isBooting, setIsBooting] = useState(true);

  return (
    <main className="relative h-screen w-screen overflow-hidden bg-[#0a0a0c]">
      {isBooting && (
        <BootSequence
          nourPath={nourPath}
          nourViewBox={nourViewBox}
          nourStrokeWidth={nourStrokeWidth}
          onComplete={() => setIsBooting(false)}
        />
      )}
    <>
      <header className="top">
        <div className="mark"><span className="dot"></span>YOURNAME</div>
        <nav className="top-links"></nav>
      </header>

      <div className="intro">
        <div className="eyebrow">Home</div>
        <h1>Everything I'm building.</h1>
        <p>Tap into any of these and it opens up into its own full site — but it's all one place.</p>
      </div>

      <div className="grid">
        {Object.values(projects).map((p) => (
          <Link 
            href={`/project/${p.id}`} 
            key={p.id}
            className="tile" 
            style={{ 
              background: p.color, 
              color: p.accent, 
              viewTransitionName: `tile-${p.id}` 
            } as React.CSSProperties}
          >
            <div className="glyph">{ICONS[p.id]}</div>
            <div>
              <div className="label" style={{ color: 'var(--bone)' }}>{p.title}</div>
              <div className="sub">{p.tag}</div>
            </div>
          </Link>
        ))}
        <div className="tile stub">
          <div className="label">+ Next</div>
        </div>
      </div>
    </>
    </main>
  );
}