"use client";
import { motion } from "framer-motion";
import type { NourPath } from "@/lib/nour-path";

export default function BootSequence({
  onComplete,
  nourPath,
  nourViewBox,
  nourStrokeWidth,
}: {
  onComplete: () => void;
  nourPath: NourPath;
  nourViewBox: string;
  nourStrokeWidth: number;
}) {
  // nour.svg is a single hand-drawn signature made of 9 separate pen
  // strokes with small real gaps between them. nour-path.ts welds all 9,
  // in the correct N -> O -> U -> R order, into ONE continuous subpath
  // (single leading "M", every gap bridged with a straight "L" instead of
  // a new "M"). Because it's genuinely one path, it's drawn here as a
  // SINGLE <motion.path> with a single pathLength tween from 0 to 1.
  //
  // This is deliberate, not just simpler: with 9 separate <motion.path>
  // elements (an earlier version of this file), each one had its own
  // independently-computed delay/duration, and however carefully those
  // were synced, they were still 9 separate timelines — small drift
  // between them could make the browser paint one path starting a beat
  // before or after the previous one had actually finished, which read
  // as the pen jumping ahead a few cm and then snapping a line back to
  // reconnect. A single path with a single tween can't drift out of sync
  // with itself — the browser guarantees pathLength grows continuously
  // from 0 to 1, so the line only ever extends forward, never jumps.
  const DRAW_DURATION = 2.4; // total pen-drawing time
  const HOLD = 2.5; // pause on the finished logo before it fades away

  const DRAW_DONE = DRAW_DURATION;
  const FADE_DELAY = DRAW_DONE + HOLD;

  return (
    <motion.div
      className="fixed inset-0 z-50 flex items-center justify-center bg-[#050505] p-8"
      initial={{ opacity: 1 }}
      animate={{ opacity: 0 }}
      transition={{ delay: FADE_DELAY, duration: 0.8, ease: "easeInOut" }}
      onAnimationComplete={onComplete}
    >
      <svg
        className="w-full max-w-3xl overflow-visible"
        viewBox={nourViewBox}
        fill="none"
      >
        {/* Main stroke — one continuous pen motion, start to finish, at
            the artwork's real thickness, in its real coordinate frame. */}
        <motion.path
          d={nourPath.d}
          stroke="#ffffff"
          strokeWidth={nourStrokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          fill="none"
          initial={{ pathLength: 0 }}
          animate={{ pathLength: 1 }}
          transition={{ duration: DRAW_DURATION, ease: "easeInOut" }}
        />

        {/* Thin bright tracer riding the leading edge, for the "laser"
            feel — same single path, same single tween, fading out once
            the draw completes. */}
        <motion.path
          d={nourPath.d}
          stroke="#ffffff"
          strokeWidth={Math.max(nourStrokeWidth * 0.6, 1)}
          strokeLinecap="round"
          strokeLinejoin="round"
          fill="none"
          initial={{ pathLength: 0, opacity: 1 }}
          animate={{ pathLength: 1, opacity: 0 }}
          transition={{
            pathLength: { duration: DRAW_DURATION, ease: "easeInOut" },
            opacity: { delay: DRAW_DONE, duration: 0.3, ease: "easeInOut" },
          }}
        />
      </svg>
    </motion.div>
  );
}